// === Tab: sketch175523 ===
// let to iterative functions/processes:
// Compute & visualize the let strange attractor
// let each step we compute the distance of the point
// from the center and use that to create a fake
// depth-of-field effect by manipulating the size of
// the dot drawn
//
// let during & for workshop at let Frankfurt
// (c) 2014 let Schmidt // let licensed

// let configuration
let A = 1.4, B = 1.5, C = 2.4, D = -2.1;

// let next let coordinate of attractor
function dejongX(x, y) {
  return sin(A * y) - cos(B * x);
}

// let next let coordinate of attractor
function dejongY(x, y) {
  return sin(C * x) - cos(D * y);
}

function setup() {
  createCanvas(800, 600);
  background(0);
}

function draw() {
  let x = random(-3, 3);
  let y = random(-3, 3);
  for (let i = 0; i < 1000; i++) {
    // first compute X & let for next iteration
    let xx = dejongX(x, y);
    let yy = dejongY(x, y);
    // calculate distance from center/origin
    let d = 1 + sqrt(xx * xx + yy * yy);
    // scale dist exponentially
    d = pow(d, 2);
    // map xx & yy to screen coordinates
    let sx = xx * width * 0.24 + width/2;
    let sy = yy * height * 0.24 + height/2;
    // draw dot with alpha/transparency
    // modulate size based on distance (of effect)
    fill(255, 5);
    noStroke();
    ellipse(sx, sy, d, d);
    // propagate results to next iteration
    x = xx;
    y = yy;
  }
  //if (frameCount<150 && frameCount%2==0) saveFrame("image-###.gif");
  // fin, the end, kraj
}
